function zipFiles(files){const enc=new TextEncoder(),local=[],central=[];let offset=0;for(const f of files){const bytes=typeof f.data==='string'?enc.encode(f.data):new Uint8Array(f.data instanceof ArrayBuffer?f.data:f.data.buffer),fn=enc.encode(f.name),crc=crc32(bytes),n=bytes.length;const lh=new Uint8Array(30+fn.length),cd=new Uint8Array(46+fn.length);let d=new DataView(lh.buffer);d.setUint32(0,0x04034b50,true);d.setUint16(4,20,true);d.setUint16(12,0x21,true);d.setUint32(14,crc,true);d.setUint32(18,n,true);d.setUint32(22,n,true);d.setUint16(26,fn.length,true);lh.set(fn,30);d=new DataView(cd.buffer);d.setUint32(0,0x02014b50,true);d.setUint16(4,20,true);d.setUint16(6,20,true);d.setUint16(14,0x21,true);d.setUint32(16,crc,true);d.setUint32(20,n,true);d.setUint32(24,n,true);d.setUint16(28,fn.length,true);d.setUint32(42,offset,true);cd.set(fn,46);local.push(lh,bytes);central.push(cd);offset+=lh.length+n;}
 let cdSize=central.reduce((a,c)=>a+c.length,0);const end=new Uint8Array(22),d=new DataView(end.buffer);d.setUint32(0,0x06054b50,true);d.setUint16(8,files.length,true);d.setUint16(10,files.length,true);d.setUint32(12,cdSize,true);d.setUint32(16,offset,true);const out=new Uint8Array(offset+cdSize+22);let o=0;for(const b of local.concat(central,[end])){out.set(b,o);o+=b.length;}return out;}
$('sleeveExport').onclick=()=>{if(!project.joints?.on){toast('Turn on joint sleeves first');return;}const files=[];buildSleeves(1).forEach((sl,i)=>{/* export at 1 mm rows: closer fit than the 2 mm preview, same guaranteed gap */if(sl&&sl.mesh&&sl.mesh.report.closed)files.push({name:filename(project.name)+'-joint-'+(i+1)+'-'+(i+2)+'-sleeve.stl',data:E.stl(JointEngine.forPrint(sl.mesh))});});if(!files.length){toast('No sleeves to export. Match the section rims first.');return;}download(filename(project.name)+'-joint-sleeves.zip',zipFiles(files),'application/zip');toast(files.length+' sleeve STL'+(files.length>1?'s':'')+' downloaded in a .zip');};
